      "title": "Format Currency Value",
      "category": "backend",
      "templateCode": "def format_currency_value(ctx, *, value, symbol: str='$', separator: str=',', decimals: int=2) -> dict:\n    num = round_half_up(to_number(value, 'value'), decimals)\n    sign = '-' if num < 0 else ''\n    num = abs(num)\n    parts = f'{num:.{decimals}f}'.split('.')\n    whole = parts[0]\n    if separator:\n        whole = f'{int(whole):,}'.replace(',', separator)\n    text = f'{sign}{symbol}{whole}.{parts[1]}'\n    return {'text': text}",
